@push('scripts')<script>$(function(){var $t=$('#eac-table'),x=$.fn.dataTable.render.text(),labels={DRAFT:'ร่าง',SUBMITTED:'รออนุมัติ',APPROVED:'อนุมัติแล้ว',POSTED:'ลงบัญชีแล้ว',CLEARED:'เคลียร์แล้ว',VOID:'ยกเลิก',REVERSED:'ยกเลิกรายการแล้ว'},classes={DRAFT:'app-status-neutral',SUBMITTED:'app-status-info',APPROVED:'app-status-success',POSTED:'app-status-success',CLEARED:'app-status-success',VOID:'app-status-danger',REVERSED:'app-status-danger'};var table=$t.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:$t.data('url'),data:function(d){d.status=$('#eac-status').val();}},order:[[1,'desc']],buttons:[window.erpExcelButton($t)],columns:[{data:'document_number',render:x.display},{data:'date_label',render:x.display},{data:'advance_label',render:x.display},{data:'net_expense_amount',className:'text-end',render:$.fn.dataTable.render.number(',','.',2)},{data:'refund_amount',className:'text-end',render:$.fn.dataTable.render.number(',','.',2)},{data:'additional_amount',className:'text-end',render:$.fn.dataTable.render.number(',','.',2)},{data:'status',render:function(v,t){return t==='display'?'<span class="badge '+(classes[v]||'app-status-neutral')+'">'+x.display(labels[v]||v)+'</span>':v;}},{data:null,orderable:false,searchable:false,className:'text-end',render:function(_,t,r){return t==='display'?'<a class="btn btn-sm btn-app-soft" href="'+x.display(r.show_url)+'" aria-label="ดูรายละเอียด"><i class="bx bx-show"></i></a>':'';}}]}));$('#eac-status').on('change',function(){table.ajax.reload();});$('#eac-reset').on('click',function(){$('#eac-status').val('');table.ajax.reload();});});</script>@endpush
